/** Filters: single-select chip groups (AND across groups) toggling `hidden` on grid items; derived groups; URL state. */
import { on, emit } from "../utils/events.js";
import { qs, qsa } from "../utils/dom.js";

const norm = (s) => (s || "").trim().toLowerCase().replace(/\s+/g, " ");

export default function init(root, opts = {}) {
  const target = opts.filterFor ? document.getElementById(String(opts.filterFor)) : root.nextElementSibling;
  const list = target && qs("[data-mhs-filter-list]", target);
  if (!list) return {};
  const items = () => qsa(".w-dyn-item, [data-mhs-filter-item]", list);
  const status = qs("[data-mhs-filter-status]", root);
  const empty = qs("[data-mhs-filter-empty]", target);
  const label = opts.filterLabel || "results"; const labelOne = opts.filterLabelOne || label.replace(/s$/, "");
  const useUrl = opts.filterUrl !== false;
  const state = {};

  // derived groups: build chips from the distinct item values, in DOM order
  qsa("[data-mhs-filter-derive]", root).forEach((box) => {
    const field = box.dataset.mhsFilterDerive; const seen = new Set();
    items().forEach((it) => { const v = (it.dataset[camel(field)] || "").trim(); if (v && !seen.has(norm(v))) { seen.add(norm(v)); box.appendChild(chip(field, v)); } });
  });

  function camel(field) { return "mhsFilter" + field.charAt(0).toUpperCase() + field.slice(1); }
  function chip(field, value) { const b = document.createElement("button"); b.type = "button"; b.className = "c-chip"; b.setAttribute("aria-pressed", "false"); b.dataset.mhsFilterField = field; b.dataset.mhsFilterValue = value; b.textContent = value; return b; }
  function valueOf(btn) { return btn.hasAttribute("data-mhs-filter-all") ? null : (btn.dataset.mhsFilterValue ?? btn.textContent); }

  function paint() {
    qsa("[data-mhs-filter-field]", root).forEach((b) => {
      const f = b.dataset.mhsFilterField; const v = valueOf(b);
      const active = v === null ? !state[f] : norm(state[f]) === norm(v);
      b.classList.toggle("is-active", active); b.setAttribute("aria-pressed", String(active));
    });
  }
  function apply() {
    let n = 0;
    items().forEach((it) => {
      const show = Object.entries(state).every(([f, v]) => !v || norm(it.dataset[camel(f)]) === norm(v));
      it.hidden = !show; if (show) n++;
    });
    if (status) status.textContent = `${n} ${n === 1 ? labelOne : label}`;
    if (empty) empty.hidden = n > 0;
    if (useUrl && "history" in window) {
      const url = new URL(location.href);
      Object.entries(state).forEach(([f, v]) => v ? url.searchParams.set(f, v) : url.searchParams.delete(f));
      history.replaceState(null, "", url);
    }
    paint();
    emit("mhs:filter:change", { state: { ...state }, count: n }, list);
  }

  on(root, "click", "[data-mhs-filter-field]", (e, btn) => {
    e.preventDefault();
    const f = btn.dataset.mhsFilterField; const v = valueOf(btn);
    state[f] = v === null || norm(state[f]) === norm(v) ? null : v;
    apply();
  });

  if (useUrl) { const p = new URLSearchParams(location.search); qsa("[data-mhs-filter-group]", root).forEach((g) => { const f = g.dataset.mhsFilterGroup; if (p.get(f)) state[f] = p.get(f); }); }
  apply();
  return { destroy() {} };
}
